# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Seed refusal once a Timekeeping handoff has begun" do
  before { allow($stdout).to receive(:write) }

  # "A missing ownership row counts as begun."
  # "`db/seeds/timesheet_data.rb`: refuse before its first write."
  it "timesheet_data refuses with no ownership row, writes no company and leaves the ownership table empty" do
    TimekeepingOwnership.delete_all
    company_baseline = Company.count

    expect { load Rails.root.join("db/seeds/timesheet_data.rb") }
      .to raise_error(TimekeepingOwnership::HandoffBegun)

    expect(Company.count).to eq(company_baseline)
    expect(Company.exists?(name: "Test Company")).to be(false)
    expect(TimekeepingOwnership.count).to eq(0)
  end

  # "`db/seeds.rb`: refuse right after `TimekeepingOwnership.ensure_initial!` (line 155) and before the company update."
  it "db/seeds.rb refuses while a handoff step is set, leaves the existing company unchanged and keeps the begun ownership row" do
    company = create(:company, name: "Fork & Leaf Salads", business_phone: "+1 2025550123")
    TimekeepingOwnership.current.update_columns(generation: 1, handoff_step: "close_admission", owner: "monolith", monolith_store: "legacy")
    baseline = company.reload.attributes
    expect(baseline["business_phone"]).to eq("+1 2025550123")

    expect { load Rails.root.join("db/seeds.rb") }
      .to raise_error(TimekeepingOwnership::HandoffBegun)

    expect(company.reload.attributes).to eq(baseline)
    expect(TimekeepingOwnership.pluck(:generation, :handoff_step, :owner, :monolith_store))
      .to eq([[1, "close_admission", "monolith", "legacy"]])
  end

  # If ensure_initial! reset an existing row, the prepared store after a rollback would quietly reseed.
  it "refuses db/seeds.rb after a rollback without ensure_initial! resetting the begun row" do
    company = create(:company, name: "Fork & Leaf Salads", business_phone: "+1 5035550199")
    TimekeepingOwnership.current.update_columns(generation: 2, handoff_step: nil, owner: "monolith", monolith_store: "prepared")
    expect(company.reload.business_phone).to eq("+1 5035550199")

    expect { load Rails.root.join("db/seeds.rb") }
      .to raise_error(TimekeepingOwnership::HandoffBegun)

    expect(company.reload.business_phone).to eq("+1 5035550199")
    expect(Company.where(name: "Copper Kettle Bakery").count).to eq(0)
    expect(TimekeepingOwnership.pluck(:generation, :owner, :monolith_store)).to eq([[2, "monolith", "prepared"]])
  end

  it "refuses both seed files for every company when an unrelated company exists and the global handoff has begun" do
    create(:company, name: "Unrelated Co")
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(monolith_store: "prepared", generation: 2)
    company_count = Company.count
    expect(Company.where(name: ["Fork & Leaf Salads", "Copper Kettle Bakery", "Test Company"]).count).to eq(0)

    # "The ownership record is one global row, so this refusal applies to every company at once."
    expect { load Rails.root.join("db/seeds.rb") }.to raise_error(TimekeepingOwnership::HandoffBegun)
    expect { load Rails.root.join("db/seeds/timesheet_data.rb") }.to raise_error(TimekeepingOwnership::HandoffBegun)

    expect(Company.count).to eq(company_count)
    expect(Company.where(name: ["Fork & Leaf Salads", "Copper Kettle Bakery", "Test Company"]).count).to eq(0)
    expect(TimekeepingOwnership.pluck(:monolith_store, :generation)).to eq([["prepared", 2]])
  end

  # "The initial legacy state still seeds and destroys as today"
  it "db/seeds/timesheet_data.rb gets past the ownership check in the initial legacy state" do
    TimekeepingOwnership.current.update_columns(generation: 1, handoff_step: nil, owner: "monolith", monolith_store: "legacy")
    # The script supplies only a name and phone for its company, which Company's
    # validations reject, so a valid one is created first.
    create(:company, name: "Test Company")

    raised = nil
    begin
      load Rails.root.join("db/seeds/timesheet_data.rb")
    rescue StandardError => error
      raised = error
    end

    expect(raised).not_to be_a(TimekeepingOwnership::HandoffBegun)
    expect(TimekeepingOwnership.pluck(:generation, :handoff_step, :owner, :monolith_store))
      .to eq([[1, nil, "monolith", "legacy"]])
  end
end
